using ASodium;
using System;
using ExtendedNumerics;
using System.Numerics;

namespace BCASodium
{
    public static class AlternateKeyExchange
    {
        //https://www.mdpi.com/2410-387X/4/1/5/pdf
        //https://asecuritysite.com/keyexchange/alt_diffie

        private static BigDecimal x = BigDecimal.Parse("0.");

        public static Byte[] GeneratePrivateKey(int Size = 32)
        {
            if (Size < 32)
            {
                throw new ArgumentException("Private key length must not be smaller than 32 bytes or 256 bits");
            }
            return SodiumRNG.GetRandomBytes(Size);
        }

        public static BigDecimal GeneratePublicKey(Byte[] PrivateKey, Boolean ClearKey = false)
        {
            if (PrivateKey == null)
                throw new ArgumentNullException("Private Key must not be null");
            if (PrivateKey.Length < 32)
                throw new ArgumentException("Private key length must be at least 32 bytes or 256 bits in length");

            BigDecimal PublicKey = BigDecimal.Multiply(x, new BigDecimal(new BigInteger(PrivateKey)));
            PublicKey = BigDecimal.Mod(PublicKey, 1);

            if (ClearKey == true)
            {
                SodiumSecureMemory.SecureClearBytes(PrivateKey);
            }

            return PublicKey;
        }

        //Better apply KDF or Hashing because the shared secret is way too big
        //for any symmetric encryption algorithm..
        public static Byte[] GenerateSharedSecret(Byte[] PrivateKey, BigDecimal OtherPublicKey, Boolean ClearKey = false)
        {
            if (PrivateKey == null)
                throw new ArgumentNullException("Private Key must not be null");
            if (PrivateKey.Length < 32)
                throw new ArgumentException("Private key length must be at least 32 bytes or 256 bits in length");
            if (OtherPublicKey == 0)
                throw new ArgumentException("Other public key must not be default value 0");
            BigDecimal SharedSecretBD = BigDecimal.Multiply(OtherPublicKey, new BigDecimal(new BigInteger(PrivateKey)));
            SharedSecretBD = BigDecimal.Mod(SharedSecretBD, 1);
            String SharedSecretString = SharedSecretBD.ToString().Substring(4);
            //If using ASCII encoding to convert the string into byte array
            //It will be approximate 4096 bytes for the sharedsecret

            //Not sure if it will be helpful but I convert the string into biginteger
            //followed by converting the biginteger back into byte array
            //The size of the sharedsecret will be 2076 bytes
            BigInteger SharedSecretBigInteger = BigInteger.Parse(SharedSecretString);
            Byte[] SharedSecret = SharedSecretBigInteger.ToByteArray();

            if (ClearKey == true)
            {
                SodiumSecureMemory.SecureClearBytes(PrivateKey);
            }

            return SharedSecret;
        }
    }
}
